// Generates supabase/seed.sql from the fixture data. Run: node --experimental-strip-types scripts/generate-seed.ts
import { writeFileSync } from "node:fs";
import { URC_FIXTURES } from "../src/lib/data/urc-2026-27.ts";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const lines = [
  "-- Generated by scripts/generate-seed.ts. Safe to re-run.",
  "insert into public.competitions (id, name, short_name) values ('urc', 'United Rugby Championship', 'URC') on conflict (id) do nothing;",
  "insert into public.seasons (id, competition_id, name, team_count, knockout_rounds) values ('urc-2026-27', 'urc', '2026/27', 16, '{19,20,21}') on conflict (id) do nothing;",
  "insert into public.fixtures (id, season_id, round, home, away, kickoff) values",
  URC_FIXTURES.map((f) => `  (${q(f.id)}, 'urc-2026-27', ${f.round}, ${q(f.home)}, ${q(f.away)}, ${q(f.kickoff)})`).join(",\n") +
    "\non conflict (id) do update set round = excluded.round, home = excluded.home, away = excluded.away, kickoff = excluded.kickoff;",
  "insert into public.games (id, season_id, name, first_round, is_public) values ('urc-2026-27-main', 'urc-2026-27', 'URC 2026/27 Last Man Standing', 6, true) on conflict (id) do nothing;",
];
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n") + "\n");
console.log(`Wrote ${URC_FIXTURES.length} fixtures`);
